let usingLocalData = false;
let EXP_NAMES = LOCAL_EXP_NAMES;
let RAW_DATA = LOCAL_RAW_DATA;



// ==========================================
// 2. APP STATE
// ==========================================
let allData = [];
let filteredData = [];
let currentPage = 0;
const PAGE_SIZE = 24;
let activeFilter = "ALL";
let activeExpedition = "ALL";
let searchQuery = "";

// ==========================================
// 3. INITIALIZE
// ==========================================
async function init() {
  const initH5 = document.getElementById("initialState").querySelector("h5");
  const initP = document.getElementById("initialState").querySelector("p");
  
  if (initH5 && initP) {
      initH5.textContent = "Memuat Data...";
      initP.textContent = "Sedang mensinkronkan dengan server, mohon tunggu...";
  }

  try {
    const res = await fetch('api_coverage.php');
    if (!res.ok) throw new Error('Network response was not ok');
    const data = await res.json();
    if (data.exp_names && data.raw_data) {
        EXP_NAMES = data.exp_names;
        RAW_DATA = data.raw_data;
        usingLocalData = false;
    } else {
        throw new Error('Data format error');
    }
  } catch (error) {
    console.error('Fetch error:', error);
    EXP_NAMES = LOCAL_EXP_NAMES;
    RAW_DATA = LOCAL_RAW_DATA;
    usingLocalData = true;
    
    const notifHtml = `<div class="alert alert-warning alert-dismissible fade show shadow-sm border-warning border-opacity-50 mx-4 mt-4 mb-0" role="alert">
        <i class="fas fa-exclamation-triangle me-2 text-warning"></i>
        <strong>Peringatan!</strong> Gagal memuat data dari server Firebase. Sistem saat ini menggunakan <strong>Data Lokal</strong> bawaan secara sementara.
        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
    </div>`;
    const hero = document.querySelector('.app-hero');
    if (hero) hero.insertAdjacentHTML('afterend', notifHtml);
  } finally {
    if (initH5 && initP) {
        initH5.textContent = "Cek Coverage";
        initP.textContent = "Masukkan minimal 3 huruf nama kecamatan atau kabupaten/kota untuk mulai pencarian.";
    }
  }

  allData = RAW_DATA;
  document.getElementById("totalDataCount").textContent = allData.length.toLocaleString("id-ID");
  document.getElementById("searchInput").addEventListener("input", debounce(onSearch, 250));
  document.getElementById("searchInput").addEventListener("keydown", e => {
    if (e.key === "Escape") clearSearch();
  });

  // Populate Expedition Filter
  const expSelect = document.getElementById("expeditionFilter");
  if (expSelect) {
    EXP_NAMES.forEach((name, i) => {
      const opt = document.createElement("option");
      opt.value = i;
      opt.textContent = name;
      expSelect.appendChild(opt);
    });
  }
}

// ==========================================
// 4. SEARCH & FILTER LOGIC
// ==========================================
function onSearch() {
  const val = document.getElementById("searchInput").value.trim();
  searchQuery = val;
  const clearBtn = document.getElementById("searchClear");
  clearBtn.classList.toggle("visible", val.length > 0);

  if (val.length < 3) {
    showInitialState();
    return;
  }
  applyFilter();
}

function setFilter(cat, btn) {
  activeFilter = cat;
  document.querySelectorAll(".filter-btn").forEach(b => b.classList.remove("active"));
  btn.classList.add("active");
  if (searchQuery.length >= 3) applyFilter();
}

function setExpeditionFilter(val) {
  activeExpedition = val;
  if (searchQuery.length >= 3) applyFilter();
}

function applyFilter() {
  const q = searchQuery.toLowerCase();
  let results = allData.filter(r => {
    const matchSearch = r[2].toLowerCase().includes(q) || r[1].toLowerCase().includes(q);
    const matchCat = activeFilter === "ALL" || r[4] === activeFilter;
    const matchExp = activeExpedition === "ALL" || r[3][parseInt(activeExpedition)] === "1";
    return matchSearch && matchCat && matchExp;
  });

  // Sort by relevance
  results.sort((a, b) => {
    const kecA = a[2].toLowerCase();
    const kecB = b[2].toLowerCase();
    
    // Priority 1: Exact match on Kecamatan
    const exactA = kecA === q;
    const exactB = kecB === q;
    if (exactA && !exactB) return -1;
    if (!exactA && exactB) return 1;

    // Priority 2: Starts with on Kecamatan
    const startsA = kecA.startsWith(q);
    const startsB = kecB.startsWith(q);
    if (startsA && !startsB) return -1;
    if (!startsA && startsB) return 1;

    // Default: Sort alphabetically by Kecamatan
    return kecA.localeCompare(kecB);
  });

  filteredData = results;
  currentPage = 0;
  renderCards(true);
}

function setSearch(val) {
  document.getElementById("searchInput").value = val;
  document.getElementById("searchClear").classList.add("visible");
  searchQuery = val;
  applyFilter();
}

function clearSearch() {
  document.getElementById("searchInput").value = "";
  searchQuery = "";
  document.getElementById("searchClear").classList.remove("visible");
  showInitialState();
  document.getElementById("searchInput").focus();
}

function showInitialState() {
  filteredData = [];
  document.getElementById("cardsContainer").innerHTML = "";
  document.getElementById("emptyState").classList.add("d-none");
  document.getElementById("initialState").classList.remove("d-none");
  document.getElementById("loadMoreWrap").classList.add("d-none");
  document.getElementById("resultCount").textContent = "0";
}

// ==========================================
// 5. RENDER CARDS
// ==========================================
function renderCards(reset) {
  const container = document.getElementById("cardsContainer");
  document.getElementById("initialState").classList.add("d-none");

  if (filteredData.length === 0) {
    container.innerHTML = "";
    document.getElementById("emptyState").classList.remove("d-none");
    document.getElementById("loadMoreWrap").classList.add("d-none");
    document.getElementById("resultCount").textContent = "0";
    return;
  }

  document.getElementById("emptyState").classList.add("d-none");
  document.getElementById("resultCount").textContent = filteredData.length.toLocaleString("id-ID");

  const start = currentPage * PAGE_SIZE;
  const end = Math.min(start + PAGE_SIZE, filteredData.length);
  const slice = filteredData.slice(start, end);

  if (reset) {
    container.innerHTML = "";
  }

  const fragment = document.createDocumentFragment();
  slice.forEach((row, i) => {
    const el = document.createElement("div");
    el.innerHTML = buildCard(row, start + i);
    fragment.appendChild(el.firstChild);
  });
  container.appendChild(fragment);

  // Animate new cards
  const cards = container.querySelectorAll(".coverage-card:not(.animated)");
  cards.forEach((c, i) => {
    c.style.opacity = "0";
    c.style.transform = "translateY(12px)";
    setTimeout(() => {
      c.style.transition = "opacity 0.3s ease, transform 0.3s ease";
      c.style.opacity = "1";
      c.style.transform = "translateY(0)";
      c.classList.add("animated");
    }, i * 35);
  });

  // Load more button
  const remaining = filteredData.length - end;
  const loadWrap = document.getElementById("loadMoreWrap");
  if (remaining > 0) {
    loadWrap.classList.remove("d-none");
    document.getElementById("loadMoreCount").textContent = `+${remaining}`;
  } else {
    loadWrap.classList.add("d-none");
  }
}

function loadMore() {
  currentPage++;
  renderCards(false);
  setTimeout(() => {
    const cards = document.querySelectorAll(".coverage-card");
    if (cards.length) cards[cards.length - PAGE_SIZE < 0 ? 0 : cards.length - PAGE_SIZE].scrollIntoView({ behavior: "smooth", block: "start" });
  }, 100);
}

// ==========================================
// 6. BUILD CARD HTML
// ==========================================
function buildCard(row, idx) {
  const [provinsi, kota, kecamatan, bits, kat] = row;
  const expAvail = bits.split("").map(b => b === "1");
  const availList = EXP_NAMES.filter((_, i) => expAvail[i]);
  const totalAvail = availList.length;

  // Category meta (Diubah ke Bahasa CS)
  const catMeta = {
    R: { label: "🔴 Sangat Lengkap", css: "kat-R", desc: "Banyak Pilihan Ekspedisi" },
    V: { label: "🟢 Tersedia", css: "kat-V", desc: "Tersedia Beberapa Ekspedisi" },
    T: { label: "🔵 Terbatas", css: "kat-T", desc: `Hanya ${totalAvail} Ekspedisi` },
    M: { label: "🟡 Eksp. Tunggal", css: "kat-M", desc: "Hanya 1 Ekspedisi" },
    B: { label: "⚫ Belum Terjangkau", css: "kat-B", desc: "Belum Ada Coverage" },
  };
  const meta = catMeta[kat] || catMeta.B;

  // Build expedition badges
  const expBadges = EXP_NAMES.map((name, i) => {
    const ok = expAvail[i];
    const shortName = name; // Sengaja tidak disingkat
    return `<div class="exp-badge ${ok ? "available" : "unavailable"}">
      <span class="exp-icon">${ok ? "✅" : "❌"}</span>
      <span class="exp-name">${shortName}</span>
    </div>`;
  }).join("");

  // Short provinsi
  const provShort = provinsi.replace("NUSA TENGGARA BARAT NTB", "NTB")
    .replace("NUSA TENGGARA TIMUR NTT", "NTT")
    .replace("DKI JAKARTA", "DKI Jakarta")
    .replace("DI YOGYAKARTA", "DIY");

  // Filter List Ekspedisi yang mati/unavailable
  const unavailList = EXP_NAMES.filter((_, i) => !expAvail[i]);

  // FIX QUOTES UNTUK TOMBOL (ESCAPE HTML)
  // Ini yang bikin tombolnya mati karena nabrak kutip
  const esc = (str) => String(str).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  const kecJson = esc(JSON.stringify(kecamatan));
  const availJson = esc(JSON.stringify(availList));
  const katJson = esc(JSON.stringify(kat));
  const kotaJson = esc(JSON.stringify(kota));
  const provJson = esc(JSON.stringify(provShort));
  const unavailJson = esc(JSON.stringify(unavailList));

  return `
<div class="coverage-card cat-${kat}" data-idx="${idx}">
  <div class="card-head">
    <div class="card-location">
      <i class="bi bi-geo-alt-fill" style="color:var(--accent)"></i>
      ${kota} &bull; ${provShort}
    </div>
    <div class="card-title">
      Kec. <span class="kec-name">${kecamatan}</span>
      <span class="total-exp-count">${totalAvail} Eksp</span>
    </div>
  </div>
  <div class="card-body-inner">
    <div class="exp-grid">${expBadges}</div>
  </div>
  <div class="card-foot d-flex justify-content-between">
    <div class="d-flex align-items-center gap-2">
        <span class="kat-badge ${meta.css}" title="${meta.desc}">${meta.label}</span>
    </div>
    <div class="d-flex gap-2">
        <button class="btn btn-sm btn-outline-danger" onclick="reportCourier(this, ${kecJson}, ${kotaJson}, ${provJson}, ${unavailJson})" title="Lapor buka rute ke Ekspedisi">
            <i class="bi bi-exclamation-octagon"></i> Lapor
        </button>
        <button class="btn-wa-copy m-0" onclick="copyWA(this, ${kecJson}, ${availJson}, ${katJson})" title="Copy pesan WA untuk kecamatan ini">
          <i class="bi bi-whatsapp"></i> Copy WA
        </button>
    </div>
  </div>
</div>`.trim();
}

// ==========================================
// 7. COPY WA MESSAGE LOGIC (DINAMIS UNTUK CS)
// ==========================================
function copyWA(btn, kecamatan, availList, kat) {
  let message = "";
  const kec = kecamatan;
  const total = availList.length;

  if (total > 1) {
    // TEMPLATE MULTI-KURIR (Lebih dari 1 pilihan)
    const listEksp = availList.map(e => `✅ ${e}`).join("\n");
    message = `Halo Kak! Selamat bergabung di SIMASRIM. 🎉\n\nKabar baik Kak! Berdasarkan pengecekan kami, area *Kecamatan ${kec}* saat ini sudah dijangkau dengan sangat baik oleh layanan Pickup GRATIS dari mitra logistik kami, yaitu:\n\n${listEksp}\n\nKakak bisa langsung input orderan dan cetak resi di aplikasi ya. Tinggal pilih ekspedisi mana yang mau dipakai, kurir akan merapat jemput paket ke depan pintu toko Kakak! 🚀📦\n\nJika butuh panduan cara cetak resinya, langsung chat kami ya.`;
  
  } else if (total === 1) {
    // TEMPLATE MONOPOLI (Hanya 1 Kurir)
    const ekspTunggal = availList[0];
    message = `Halo Kak! Terima kasih sudah menggunakan SIMASRIM. 🙏\n\nUntuk area *Kecamatan ${kec}*, saat ini layanan pickup prioritas kami yang tersedia di aplikasi Kakak adalah *${ekspTunggal}*.\n\nKakak bisa langsung cetak resinya menggunakan ekspedisi tersebut agar kurir bisa segera meluncur ke lokasi Kakak hari ini juga! 🚀✨\n\nAda kendala saat input resi? Kasih tau Mimin ya Kak.`;
  
  } else {
    // TEMPLATE BLANK SPOT (Belum ada kurir)
    message = `Halo Kak! Terima kasih sudah mendaftar di SIMASRIM. 🙏\n\nUntuk area *Kecamatan ${kec}*, saat ini sedang dalam proses pembukaan rute dengan beberapa ekspedisi rekanan kami. Tapi Kakak *TIDAK PERLU KHAWATIR*!\n\nSilakan input saja orderannya di aplikasi SIMASRIM seperti biasa. Setelah resi terbuat, infokan ke kami di chat ini ya Kak. Nanti tim Pusat SIMASRIM yang akan langsung menelepon Kepala Cabang Ekspedisi terdekat agar mereka mengirimkan armada khusus untuk melakukan Pickup ke lokasi Kakak. 🚀📦`;
  }

  // Copy to clipboard
  navigator.clipboard.writeText(message).then(() => {
    btn.classList.add("copied");
    btn.innerHTML = '<i class="bi bi-check2"></i> Tersalin!';
    showToast(`💬 Pesan WA untuk Kec. ${kec} berhasil disalin!`);
    setTimeout(() => {
      btn.classList.remove("copied");
      btn.innerHTML = '<i class="bi bi-whatsapp"></i> Copy WA';
    }, 2500);
  }).catch(() => {
    const ta = document.createElement("textarea");
    ta.value = message;
    ta.style.position = "fixed"; ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.focus(); ta.select();
    document.execCommand("copy");
    document.body.removeChild(ta);
    btn.classList.add("copied");
    btn.innerHTML = '<i class="bi bi-check2"></i> Tersalin!';
    showToast(`💬 Pesan WA untuk Kec. ${kec} berhasil disalin!`);
    setTimeout(() => {
      btn.classList.remove("copied");
      btn.innerHTML = '<i class="bi bi-whatsapp"></i> Copy WA';
    }, 2500);
  });
}

// ==========================================
// 8. TOAST NOTIFICATION
// ==========================================
let toastTimer;
function showToast(msg) {
  const toast = document.getElementById("toastNotify");
  document.getElementById("toastMsg").textContent = msg;
  toast.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("show"), 3000);
}

// ==========================================
// 9. BLANK SPOT REPORT
// ==========================================
function reportBlankSpot() {
  const q = document.getElementById("searchInput").value.trim();
  const hint = q ? `Kecamatan: ${q}` : "(isi nama kecamatan di sini)";
  const msg = `🚨 *LAPORAN BLANK SPOT - SIMASRIM*\n\n📍 ${hint}\n📊 Status: Tidak ada coverage ekspedisi\n⏰ Waktu: ${new Date().toLocaleString("id-ID")}\n\n_Mohon segera koordinasikan ke PIC Ekspedisi untuk pembukaan rute baru._`;
  navigator.clipboard.writeText(msg).then(() => {
    showToast("📋 Template laporan Blank Spot disalin! Paste ke Grup WA Internal.");
  }).catch(() => showToast("Gagal menyalin. Salin manual dari konsol."));
}

// ==========================================
// 9.b. REPORT COURIER (ESKALASI 3PL)
// ==========================================
function reportCourier(btn, kecamatan, kota, provinsi, unavailList) {
  let listUnavail = "";
  if (unavailList.length > 0) {
      listUnavail = unavailList.map(e => `- ${e}`).join("\n");
  } else {
      listUnavail = "- (Semua kurir sudah aktif)";
  }

  const msg = `🚨 *REQUEST PEMBUKAAN RUTE BARU*\n\nTim Ops, mohon dibantu *push* ke PIC Ekspedisi untuk segera membuka coverage pickup di area berikut karena sedang ada prospek Agen/User yang mendaftar:\n\n📍 *Kec. ${kecamatan}, ${kota} (${provinsi})*\n\nKurir yang saat ini berstatus UNAVAILABLE:\n${listUnavail}\n\nMohon di-follow up agar user bisa segera cetak resi. Terima kasih! 🙏`;

  navigator.clipboard.writeText(msg).then(() => {
    const origHtml = btn.innerHTML;
    btn.innerHTML = '<i class="bi bi-check2"></i>';
    btn.classList.replace("btn-outline-danger", "btn-danger");
    showToast(`🚨 Template Lapor 3PL Kec. ${kecamatan} disalin!`);
    
    setTimeout(() => {
      btn.innerHTML = origHtml;
      btn.classList.replace("btn-danger", "btn-outline-danger");
    }, 2000);
  }).catch(() => showToast("Gagal menyalin."));
}

// ==========================================
// 10. UTILITY
// ==========================================
function debounce(fn, delay) {
  let t;
  return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), delay); };
}

// ==========================================
// 11. BOOT
// ==========================================
document.addEventListener("DOMContentLoaded", init);
</script>

